#include <cstddef>
#include <stdexcept>
#include <vector>

void ZeroMarkedRowsColumns(std::vector<std::vector<int>>& a) {
    const std::size_t rows = a.size();
    if (rows > 200) throw std::invalid_argument("row limit exceeded");
    if (rows == 0) return;
    const std::size_t cols = a[0].size();
    if (cols > 200) throw std::invalid_argument("column limit exceeded");
    for (const auto& row : a) {
        if (row.size() != cols)
            throw std::invalid_argument("matrix must be rectangular");
    }
    if (cols == 0) return;

    bool zeroFirstRow = false, zeroFirstCol = false;
    for (std::size_t c = 0; c < cols; ++c)
        if (a[0][c] == 0) zeroFirstRow = true;
    for (std::size_t r = 0; r < rows; ++r)
        if (a[r][0] == 0) zeroFirstCol = true;

    for (std::size_t r = 1; r < rows; ++r) {
        for (std::size_t c = 1; c < cols; ++c) {
            if (a[r][c] == 0) {
                a[r][0] = 0;
                a[0][c] = 0;
            }
        }
    }
    for (std::size_t r = 1; r < rows; ++r) {
        for (std::size_t c = 1; c < cols; ++c) {
            if (a[r][0] == 0 || a[0][c] == 0)
                a[r][c] = 0;
        }
    }
    if (zeroFirstRow)
        for (std::size_t c = 0; c < cols; ++c) a[0][c] = 0;
    if (zeroFirstCol)
        for (std::size_t r = 0; r < rows; ++r) a[r][0] = 0;
}
